// Flow: 步驟1 需要優化嗎 → 步驟2 了解資料 → 步驟3 問題要什麼 → 步驟4 演算法 → 得到了什麼 → 繼續或解決

export type AlgoNodeKind = 'root' | 'question' | 'algorithm' | 'gain' | 'outcome';

export interface AlgoNode {
  id: string;
  label: string;
  labelZh: string;
  kind: AlgoNodeKind;
  category: string;
  time: string;
  space: string;
  ds: string;
  desc: string;
  /** question nodes: 'yesno' 是非題 | 'choice' 選擇題 */
  qtype: '' | 'yesno' | 'choice';
  /** question nodes: which step of 拆解問題 (1 需要優化嗎 / 2 了解資料 / 3 問題要什麼) */
  stage: number;
  /** algorithm leaves: id of the algorithm this leaf stands for (same algorithm can be several leaves) */
  ref: string;
  /** non-built-in data structures this algorithm needs you to write (ids in customStructures) */
  customDs: string[];
}

/** kind = the kind of the edge's target node */
export interface AlgoEdge {
  from: string;
  to: string;
  reason: string;
  kind: AlgoNodeKind;
  /** answer to the question (是 / 否 / option text) */
  answer: string;
}

export interface AlgoNext {
  from: string;
  to: string;
  reason: string;
}

